INSERT INTO patients (name, gender, age, inpatient_no, phone, department, doctor, main_diagnosis, admission_time, bed_no, nursing_level, weight, height, ecog_score, physical_exam, initial_diagnosis, treatment_plan, chief_complaint, present_illness, past_history, auxiliary_examination) VALUES
('王建国', '男', 68, 'ZY2024001234', '138****5678', '肝胆外科', '张明华', '胰头癌术后', '2024-01-15 08:30:00', 'A区15床', '二级护理', 65.5, 172, 1, '神清，精神可，全身皮肤黏膜无黄染，浅表淋巴结未触及肿大。腹平软，右上腹轻压痛，无反跳痛，肝脾肋下未及，移动性浊音阴性，肠鸣音正常。', '1. 胰头癌术后；2. 糖尿病；3. 高血压', '1. 术后康复治疗；2. 定期复查CT评估病情；3. 控制血糖血压；4. 必要时化疗', '胰头癌术后1个月，要求制定后续治疗方案', '患者1个月前因胰头癌行胰十二指肠切除术，术后恢复尚可。现为进一步治疗入院。术后病理示：胰头导管腺癌，中分化，切缘阴性。术后出现血糖波动，需胰岛素控制。', '既往有2型糖尿病史5年，口服降糖药控制；高血压病史10年，服用氨氯地平控制良好。否认肝炎、结核等传染病史。否认手术外伤史（本次除外）。否认药物及食物过敏史。', '1. 术后病理：胰头导管腺癌，中分化，T2N0M0，IB期；2. 肿瘤标志物：CA19-9 125.6 U/mL，CEA 8.2 ng/mL；3. 腹部CT：术后改变，未见明显复发征象；4. 胸部CT：未见转移灶；5. 血常规：Hb 108g/L，轻度贫血；6. 肝肾功能：基本正常；7. 血糖：空腹8.5 mmol/L，餐后2h 12.3 mmol/L。'),
('李秀英', '女', 65, 'ZY2024001256', '137****2345', '肿瘤科', '陈伟', '胰腺癌晚期，姑息治疗', '2024-02-20 10:15:00', 'B区08床', '一级护理', 52.3, 158, 2, '神清，精神萎靡，全身消瘦，皮肤黏膜苍白。腹膨隆，全腹压痛，无反跳痛，肝脾肿大，移动性浊音阳性。', '1. 胰腺癌晚期伴腹腔转移；2. 恶性腹水；3. 贫血', '1. 姑息化疗；2. 腹水引流；3. 营养支持；4. 止痛治疗', '上腹痛3个月，加重伴腹胀1个月', '患者3个月前出现上腹部隐痛，呈持续性，与进食无关。近1个月腹痛加重，伴明显腹胀，食欲下降，体重减轻约8kg。外院CT示胰腺体尾部占位，腹腔多发淋巴结肿大，大量腹水。为求进一步诊治入院。', '既往体健，否认高血压、糖尿病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认药物及食物过敏史。', '1. 腹部CT：胰腺体尾部占位性病变，约6.5×5.2cm，腹腔多发淋巴结肿大，大量腹水；2. 肿瘤标志物：CA19-9 >1000 U/mL，CEA 45.6 ng/mL；3. 腹水检查：淡黄色，李凡他试验阳性，找到腺癌细胞；4. 血常规：Hb 86g/L，WBC 6.8×10^9/L；5. 肝肾功能：ALT 68 U/L，AST 72 U/L，ALB 28.5 g/L；6. 凝血功能：PT 14.2s，APTT 38.5s。'),
('张伟', '男', 58, 'ZY2024001278', '136****8901', '消化内科', '刘强', '胰腺占位，待病理', '2024-03-05 14:00:00', 'C区12床', '二级护理', 70.2, 175, 0, '神清，精神好，全身皮肤无黄染。腹平软，左上腹轻压痛，无反跳痛，肝脾未及，肠鸣音正常。', '1. 胰腺体尾部占位性病变；2. 慢性胰腺炎待排', '1. 完善胰腺增强CT；2. 超声内镜检查；3. 准备手术探查', '体检发现胰腺占位1周', '患者1周前体检时腹部超声发现胰腺体尾部低回声占位，约3.2×2.8cm，边界欠清。患者无明显腹痛，无黄疸，无消瘦，无食欲改变。为明确诊断入院。', '既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认药物及食物过敏史。吸烟史20年，约10支/日，偶饮酒。', '1. 腹部超声：胰腺体尾部低回声占位，3.2×2.8cm，边界欠清，CDFI示血流信号；2. 腹部CT平扫：胰腺体尾部低密度影，建议增强扫描；3. 肿瘤标志物：CA19-9 68.5 U/mL，CEA 4.2 ng/mL；4. 血常规：正常；5. 肝肾功能：正常；6. 血糖：空腹5.8 mmol/L；7. 心电图：窦性心律，正常心电图。'),
('刘芳', '女', 45, 'ZY2024001289', '135****3456', '肝胆外科', '赵敏', '胰体尾癌伴肝转移', '2024-01-28 09:00:00', 'A区06床', '一级护理', 48.8, 162, 2, '神清，精神差，皮肤黏膜轻度黄染。腹平软，左上腹压痛，肝区叩击痛阳性，移动性浊音阴性。', '1. 胰体尾癌；2. 肝转移；3. 梗阻性黄疸', '1. 解除胆道梗阻；2. 全身化疗；3. 肝脏局部治疗', '上腹痛2个月，皮肤黄染1周', '患者2个月前出现上腹部持续性隐痛，伴腰背部放射痛，夜间明显。近1周出现皮肤巩膜黄染，尿色加深，大便颜色变浅。外院CT示胰腺体尾部占位，肝内多发低密度影。为求进一步诊治入院。', '既往体健，否认高血压、糖尿病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认药物及食物过敏史。', '1. 腹部增强CT：胰腺体尾部占位性病变，约5.5×4.2cm，肝内多发低密度影，最大约2.8cm，考虑转移；胆总管下段受压，肝内胆管扩张；2. 肿瘤标志物：CA19-9 856.3 U/mL，CEA 32.5 ng/mL；3. 肝功能：TBIL 85.6 μmol/L，DBIL 62.3 μmol/L，ALB 32.8 g/L；4. 血常规：Hb 95g/L；5. 凝血功能：PT 15.8s；6. 胸部CT：未见转移灶。'),
('陈志强', '男', 72, 'ZY2024001290', '134****7890', '肿瘤科', '孙强', '胰腺神经内分泌肿瘤', '2024-01-10 11:30:00', 'B区18床', '二级护理', 68.0, 168, 1, '神清，精神可，全身皮肤无异常。腹平软，无压痛，肝脾未及，肠鸣音正常。', '1. 胰腺神经内分泌肿瘤（G2）；2. 高血压；3. 冠心病', '1. 生长抑素类似物治疗；2. 定期复查；3. 控制基础疾病', '体检发现胰腺占位2周', '患者2周前体检时腹部CT发现胰腺头部占位，约2.5×2.0cm，边界清楚。患者无腹痛，无黄疸，无消瘦。进一步行超声内镜检查，穿刺活检病理示神经内分泌肿瘤（G2）。为制定治疗方案入院。', '高血压病史15年，服用缬沙坦控制良好；冠心病史5年，偶有胸闷，服用阿司匹林、阿托伐他汀。否认糖尿病史。否认肝炎、结核等传染病史。否认手术外伤史。否认药物及食物过敏史。', '1. 腹部增强CT：胰腺头部占位，2.5×2.0cm，边界清楚，动脉期明显强化；2. 超声内镜：胰腺头部低回声占位，穿刺活检病理示神经内分泌肿瘤（G2），Ki-67 8%；3. 肿瘤标志物：CA19-9 12.5 U/mL，CEA 2.8 ng/mL，CgA 156.8 ng/mL；4. 血常规：正常；5. 肝肾功能：正常；6. 心电图：窦性心律，ST-T改变；7. 心脏超声：左室舒张功能减退，EF 58%。'),
('赵明', '男', 55, 'ZY2024001291', '133****4567', '胸外科', '王磊', '左肺鳞癌', '2024-02-05 09:30:00', 'C区05床', '二级护理', 72.5, 178, 1, '神清，精神可，全身皮肤无黄染。胸廓对称，双肺呼吸音粗，左肺上叶可闻及湿啰音。心率78次/分，律齐。腹软无压痛。', '1. 左肺鳞癌 IIIA期；2. 高血压', '1. 新辅助化疗；2. 手术治疗；3. 术后辅助治疗', '咳嗽、咳痰2个月，痰中带血1周', '患者2个月前无明显诱因出现咳嗽、咳痰，为阵发性刺激性干咳，偶有少量白色粘痰。近1周出现痰中带血，为鲜红色血丝。外院CT示左肺上叶占位性病变，大小约4.5cm×3.8cm。为求进一步诊治入院。', '高血压病史8年，服用氨氯地平控制。否认糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。吸烟史30年，约20支/日。否认手术外伤史。否认药物及食物过敏史。', '1. 胸部CT：左肺上叶占位性病变，4.5×3.8cm，边界不清，伴纵隔淋巴结肿大；2. 支气管镜：左肺上叶支气管新生物，活检病理示鳞状细胞癌；3. 病理报告：鳞状细胞癌，中分化，CK5/6(+)，P63(+)，TTF-1(-)；4. 肿瘤标志物：CEA 5.2ng/mL，SCC 3.8ng/mL；5. 肺功能：FEV1 2.1L，FEV1% 78%；6. 心电图：窦性心律，正常心电图。'),
('孙丽', '女', 48, 'ZY2024001292', '132****6789', '乳腺外科', '李娜', '右乳腺癌术后', '2024-01-18 14:00:00', 'A区12床', '二级护理', 58.2, 165, 0, '神清，精神好，全身皮肤无黄染。右胸壁切口愈合良好，无红肿渗液。右腋窝未触及肿大淋巴结。心肺听诊未见异常。腹软无压痛。', '1. 右乳腺癌 pT2N1M0 II期；2. ER(+) PR(+) HER2(-)', '1. 辅助化疗；2. 内分泌治疗；3. 定期复查', '右乳腺癌术后1个月，要求制定辅助治疗方案', '患者1个月前因"右乳癌"行右乳癌改良根治术，术后病理示：右乳浸润性导管癌，pT2N1M0，II期。免疫组化：ER(+)，PR(+)，HER2(-)，Ki-67(20%+)。术后恢复良好，切口愈合佳。现为求进一步辅助治疗来诊。', '既往体健，否认高血压、糖尿病等慢性病史。否认手术外伤史（本次手术除外）。否认药物及食物过敏史。无烟酒等不良嗜好。', '1. 术后病理：右乳浸润性导管癌，pT2N1M0，II期；2. 免疫组化：ER(+)，PR(+)，HER2(-)，Ki-67(20%+)；3. 血常规：WBC 6.2×10^9/L，Hb 118g/L，PLT 256×10^9/L；4. 肝肾功能：ALT 25U/L，AST 22U/L，Cr 68μmol/L；5. 心电图：窦性心律，正常心电图；6. 超声心动图：LVEF 62%，心脏结构及功能未见异常。'),
('周强', '男', 62, 'ZY2024001293', '131****8901', '呼吸内科', '张伟', '慢性阻塞性肺疾病急性加重', '2024-03-08 10:45:00', 'D区03床', '一级护理', 68.8, 170, 2, '神清，精神差，半卧位，呼吸急促，口唇轻度发绀。桶状胸，双肺呼吸音减弱，双肺可闻及散在干湿啰音。心率96次/分，律齐。腹软无压痛。双下肢轻度水肿。', '1. COPD急性加重；2. 冠心病；3. 高血压3级', '1. 抗感染治疗；2. 支气管扩张剂；3. 氧疗；4. 控制基础疾病', 'COPD病史10年，受凉后咳嗽加重3天', '患者有COPD病史10年，3天前受凉后出现咳嗽加重，咳黄脓痰，量较前增多，伴气促加重，活动后明显。无发热、胸痛、咯血等。自行服用抗生素效果不佳，遂来我院就诊。', 'COPD病史10年，间断使用吸入药物治疗。冠心病史5年，规律服用阿司匹林、美托洛尔等药物。高血压3级病史8年，规律服用氨氯地平等药物。吸烟史40年，约20支/天，已戒烟2年。', '1. 血常规：WBC 12.5×10^9/L，N 82%，Hb 145g/L；2. 血气分析：pH 7.35，PaO2 65mmHg，PaCO2 52mmHg，HCO3- 28mmol/L；3. 胸部CT：双肺透亮度增加，肺纹理增粗紊乱，双肺散在斑片状阴影；4. 肺功能：FEV1 1.2L，FEV1% 45%，FEV1/FVC 58%；5. 心电图：窦性心律，右心室肥厚；6. 超声心动图：肺动脉高压（中度），右心室扩大。'),
('吴敏', '女', 52, 'ZY2024001294', '130****1234', '消化内科', '刘洋', '胃癌术后', '2024-02-12 08:00:00', 'B区15床', '二级护理', 55.6, 160, 1, '神清，精神可，全身皮肤无黄染。腹部切口愈合良好，无红肿渗液。腹平软，无压痛，肝脾肋下未及，肠鸣音正常。', '1. 胃癌 pT3N1M0 IIB期；2. 贫血', '1. 术后辅助化疗；2. 营养支持；3. 定期复查', '胃癌术后1个月，要求制定辅助治疗方案', '患者1个月前因"胃癌"行远端胃大部切除术，术后病理示：胃窦部中分化腺癌，pT3N1M0，IIB期。术后恢复良好，切口愈合佳。现为求进一步辅助治疗来诊。', '既往体健，否认高血压、糖尿病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史（本次手术除外）。否认药物及食物过敏史。', '1. 术后病理：胃窦部中分化腺癌，pT3N1M0，IIB期；2. 血常规：Hb 98g/L，轻度贫血；3. 肝肾功能：ALT 32U/L，AST 28U/L，ALB 35.5 g/L；4. 肿瘤标志物：CEA 8.5 ng/mL，CA19-9 45.2 U/mL；5. 腹部CT：术后改变，未见明显复发征象；6. 心电图：窦性心律，正常心电图。'),
